import json, sys, collections

ev = [json.loads(l) for l in open(sys.argv[1])]
want = sys.argv[2] if len(sys.argv) > 2 else "erp:"
by = collections.defaultdict(list)
for e in ev:
    if e["worker"].startswith(want):
        by[e["worker"]].append(e)
for w, es in by.items():
    print("=====", w)
    for e in es:
        d = {k: v for k, v in e.items() if k not in ("t", "worker", "kind")}
        s = json.dumps(d, ensure_ascii=False)
        print(f"  {e['t']:7.1f} {e['kind']:<16} {s[:220]}")

